// Interactive map of the electricity demand data of the list. It draws
// the outlines of map.geojson, the countries and then the subdivisions of
// the list, each coloured by the class of its own years of data, over a
// plain sea, so that every border and coastline comes from the same
// shapes. A click on a country or subdivision lists its data sources
// from sources.json. Both files are generated by scripts/build.py next to
// this page, and the colours are those of map.css, in the reader's theme.

const CLASSES = 4;
const DARK = window.matchMedia("(prefers-color-scheme: dark)");
// The land without Antarctica, which the first view fits; on narrow
// screens, below the legend, which is at their top.
const LAND = [
  [-168, -56],
  [180, 78],
];

function legendPadding() {
  const legend = document.getElementById("legend").getBoundingClientRect();
  const narrow = window.innerWidth <= 600;
  return {
    top: narrow ? legend.bottom + 10 : 20,
    bottom: 20,
    left: 10,
    right: 50,
  };
}

function cssColour(name) {
  return getComputedStyle(document.documentElement)
    .getPropertyValue(name)
    .trim();
}

function fillColour() {
  const expression = ["match", ["get", "class"]];
  for (let i = 0; i < CLASSES; i += 1) {
    expression.push(i, cssColour(`--class-${i}`));
  }
  expression.push(cssColour("--land"));
  return expression;
}

function element(tag, text) {
  const node = document.createElement(tag);
  if (text) node.textContent = text;
  return node;
}

function link(text, url) {
  const node = element("a", text);
  node.href = url;
  node.target = "_blank";
  node.rel = "noopener";
  return node;
}

function seriesItem(series) {
  const item = element("li");
  item.append(link(series.source_name, series.url));
  const end = series.end === series.start ? "" : `-${series.end}`;
  item.append(` · ${series.start}${end} · ${series.resolution_minutes} min · `);
  item.append(link(series.licence_name, series.licence_url));
  if (series.access === "on-request") item.append(" · access on request");
  if (series.note) item.append(` · ${series.note}`);
  if (series.demandcast) item.append(" · retrieved by DemandCast");
  return item;
}

function popupContent(country, subdivision) {
  const content = element("div");
  const series = country.series.filter(
    (s) => (s.subdivision_code ?? null) === subdivision,
  );
  const name = subdivision
    ? `${series[0]?.subdivision_name ?? subdivision}, ${country.name}`
    : country.name;
  content.append(element("h3", name));
  if (series.length === 0) {
    content.append(element("p", "No national data in the list yet."));
  } else {
    const list = element("ul");
    for (const s of series) list.append(seriesItem(s));
    content.append(list);
  }
  if (!subdivision) {
    const names = [
      ...new Set(
        country.series
          .filter((s) => s.subdivision_code)
          .map((s) => s.subdivision_name),
      ),
    ];
    if (names.length) {
      content.append(
        element(
          "p",
          `Data also for ${names.length} subdivisions, drawn on the map: ` +
            `${names.join(", ")}.`,
        ),
      );
    }
  }
  return content;
}

const map = new maplibregl.Map({
  container: "map",
  style: {
    version: 8,
    sources: {},
    layers: [
      {
        id: "sea",
        type: "background",
        paint: { "background-color": cssColour("--sea") },
      },
    ],
  },
  center: [10, 25],
  zoom: 1,
  minZoom: 0.5,
  maxZoom: 7,
  renderWorldCopies: false,
  attributionControl: false,
});
map.addControl(new maplibregl.NavigationControl({ showCompass: false }));
map.addControl(
  new maplibregl.AttributionControl({
    compact: true,
    customAttribution:
      'Outlines: <a href="https://www.naturalearthdata.com/">Natural Earth</a>' +
      ' and <a href="https://github.com/open-energy-transition/demandcast">' +
      "DemandCast</a>",
  }),
);

function applyColours() {
  map.setPaintProperty("sea", "background-color", cssColour("--sea"));
  map.setPaintProperty("countries", "fill-color", fillColour());
  map.setPaintProperty("subdivisions", "fill-color", fillColour());
  map.setPaintProperty("borders", "line-color", cssColour("--border"));
}

map.on("load", async () => {
  map.fitBounds(LAND, { padding: legendPadding(), animate: false });
  const [list, shapes] = await Promise.all([
    fetch("sources.json").then((response) => response.json()),
    fetch("map.geojson").then((response) => response.json()),
  ]);
  map.addSource("shapes", { type: "geojson", data: shapes });
  map.addLayer({
    id: "countries",
    type: "fill",
    source: "shapes",
    filter: ["==", ["get", "subdivision"], null],
    paint: { "fill-color": fillColour() },
  });
  map.addLayer({
    id: "subdivisions",
    type: "fill",
    source: "shapes",
    filter: ["!=", ["get", "subdivision"], null],
    paint: { "fill-color": fillColour() },
  });
  map.addLayer({
    id: "borders",
    type: "line",
    source: "shapes",
    paint: {
      "line-color": cssColour("--border"),
      "line-width": ["interpolate", ["linear"], ["zoom"], 1, 0.3, 6, 1],
    },
  });
  DARK.addEventListener("change", applyColours);

  const layers = ["subdivisions", "countries"];
  map.on("click", (event) => {
    const [feature] = map.queryRenderedFeatures(event.point, { layers });
    const country = feature && list.countries[feature.properties.country];
    if (!country) return;
    new maplibregl.Popup({ maxWidth: "420px" })
      .setLngLat(event.lngLat)
      .setDOMContent(
        popupContent(country, feature.properties.subdivision ?? null),
      )
      .addTo(map);
  });
  map.on("mousemove", (event) => {
    const [feature] = map.queryRenderedFeatures(event.point, { layers });
    const listed = feature && list.countries[feature.properties.country];
    map.getCanvas().style.cursor = listed ? "pointer" : "";
  });
});
